<template><div><div class="page-heading"><div><span class="eyebrow">YOUR STORE, YOUR SIGNATURE</span><h1>你的精品店，你来定义。</h1><p>店铺信息与营业状态会同步到完整商城和快速小程序。</p></div><ShopQR/></div><section v-loading="loading" class="atelier-panel settings-panel"><div class="panel-toolbar"><h2>店铺信息</h2><el-button type="text" @click="load">重新加载</el-button></div><el-form label-position="top" @submit.native.prevent="save"><el-form-item label="店铺名称"><el-input v-model="form.name" maxlength="30"></el-input></el-form-item><el-form-item label="店铺公告"><el-input v-model="form.announcement" type="textarea" :rows="2" maxlength="240"></el-input></el-form-item><el-form-item label="自提地点"><el-input v-model="form.location" maxlength="80"></el-input></el-form-item><el-form-item label="营业时间"><el-input v-model="form.hours" maxlength="40"></el-input></el-form-item><el-form-item label="接受新预约"><el-switch v-model="form.open" active-text="接受预约" inactive-text="暂停预约"></el-switch><p class="form-hint">暂停时保留商品展示，停止接收新预约。</p></el-form-item><el-button type="primary" native-type="submit" :loading="saving">保存店铺设置 <i class="el-icon-right"></i></el-button></el-form></section></div></template>
<script>
import ShopQR from '@/components/ShopQR.vue'
import {loadCatalog,saveSettings} from '@/api/catalog'
export default{components:{ShopQR},data:()=>({form:{name:'',announcement:'',location:'',hours:'',open:false,version:0},loading:true,saving:false}),mounted(){this.load()},methods:{async load(){this.loading=true;try{this.form={...(await loadCatalog()).settings}}catch(e){this.$message.error(e.message)}finally{this.loading=false}},async save(){this.saving=true;try{this.form=await saveSettings(this.form);this.$message.success('店铺信息已保存')}catch(e){this.$message.error(e.message)}finally{this.saving=false}}}}
</script>
